{
  "@context": "https://schema.org",
  "@type": "TouristTrip",
  "name": "8-Day Marrakech, Sahara, Fes and Chefchaouen Tour",
  "description": "A shared, one-way group tour from Marrakech to Fes — arrival and hostel transfer, a crossing of the High Atlas via Ait Benhaddou to the Dades Gorges, a camel trek and an overnight stay at a luxury desert camp at Merzouga, guided Fes medina sightseeing, and day trips to Chefchaouen and the Middle Atlas from Fes.",
  "touristType": ["Budget travelers", "Backpackers", "Solo travelers"],
  "itinerary": {
    "@type": "ItemList",
    "itemListElement": [
      { "@type": "ListItem", "position": 1, "item": { "@type": "TouristAttraction", "name": "Day 1: Arrival in Marrakech", "description": "Airport pick-up and transfer to your hostel in the Marrakech medina. Free time to explore Jemaa el-Fnaa and the surrounding souks." } },
      { "@type": "ListItem", "position": 2, "item": { "@type": "TouristAttraction", "name": "Day 2: Marrakech to Dades Gorges", "description": "Cross the High Atlas via the Tizi n'Tichka pass, stop at the UNESCO-listed Ait Benhaddou kasbah, and continue through the Valley of Roses to an overnight stay in the Dades Gorges." } },
      { "@type": "ListItem", "position": 3, "item": { "@type": "TouristAttraction", "name": "Day 3: Dades Gorges to Merzouga Desert", "description": "Drive via Tinghir and Erfoud to Merzouga, gateway to the Sahara, then a camel ride into the Erg Chebbi dunes to reach your luxury desert camp for the night." } },
      { "@type": "ListItem", "position": 4, "item": { "@type": "TouristAttraction", "name": "Day 4: Merzouga to Fes", "description": "Morning camel ride back from the dunes, then a full day's drive north via Er-Rachidia, Midelt and the Middle Atlas to Fes. Overnight in Riad Fez Mahal or La Perle de la Medina." } },
      { "@type": "ListItem", "position": 5, "item": { "@type": "TouristAttraction", "name": "Day 5: Fes sightseeing with a local guide", "description": "Full guided day through the Fes el-Bali medina — the tanneries, souks, and the Bou Inania Madrasa. Overnight in the same Fes riad." } },
      { "@type": "ListItem", "position": 6, "item": { "@type": "TouristAttraction", "name": "Day 6: Chefchaouen excursion", "description": "Round-trip day excursion to Chefchaouen's blue-washed medina through the Rif Mountains. Overnight back in Fes, same riad." } },
      { "@type": "ListItem", "position": 7, "item": { "@type": "TouristAttraction", "name": "Day 7: Middle Atlas & Ifrane excursion", "description": "Round-trip day excursion to Ifrane and the Middle Atlas cedar forests, with a chance to spot Barbary macaques. Overnight back in Fes, same riad." } },
      { "@type": "ListItem", "position": 8, "item": { "@type": "TouristAttraction", "name": "Day 8: Transfer to Fes Airport", "description": "Transfer from your Fes riad to Fes-Saïss Airport (FEZ). Trip ends." } }
    ]
  },
  "offers": {
    "@type": "Offer",
    "priceCurrency": "EUR",
    "price": "1079",
    "availability": "https://schema.org/InStock"
  },
  "provider": {
    "@type": "TravelAgency",
    "name": "Shared Morocco Adventures",
    "url": "https://www.sharedmoroccoadventures.com"
  }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    { "@type": "Question", "name": "Is this the same as booking the 6-day tour separately?", "acceptedAnswer": { "@type": "Answer", "text": "It follows the same first 5 days, then adds a Chefchaouen day trip and a Middle Atlas/Ifrane day trip from Fes before your final departure on Day 8. This version also upgrades the Merzouga night from the 6-day tour's shared camp to a luxury desert camp with a private en-suite tent, which is reflected in the price." } },
    { "@type": "Question", "name": "Do I need to repack for the Chefchaouen and Ifrane days?", "acceptedAnswer": { "@type": "Answer", "text": "No — both are round-trip day excursions from Fes, so you stay in the same riad for all four Fes nights and don't need to pack an overnight bag." } },
    { "@type": "Question", "name": "Is accommodation shared?", "acceptedAnswer": { "@type": "Answer", "text": "Marrakech, the Dades Gorges and Fes are shared twin/dorm rooms, but the €1,079 price includes a private en-suite tent at a luxury desert camp in Merzouga for the Sahara night. A private room upgrade for the other nights is available on request for an additional cost." } },
    { "@type": "Question", "name": "What should I pack for the desert night?", "acceptedAnswer": { "@type": "Answer", "text": "Desert nights get cold even in summer — bring a warm layer, plus sunscreen, a scarf or hat for wind and sun, and comfortable walking shoes." } },
    { "@type": "Question", "name": "Is this trip one-way, or does it return to Marrakech?", "acceptedAnswer": { "@type": "Answer", "text": "One-way — you're picked up in Marrakech on Day 1 and dropped off in Fes on Day 8." } },
    { "@type": "Question", "name": "What if the group doesn't fill up?", "acceptedAnswer": { "@type": "Answer", "text": "Departures run on fixed weekly dates regardless of group size — your trip runs even if only a few seats are booked." } }
  ]
}
